<div class="nc-slider-controls" hidden><div><button type="button" data-slide-prev aria-label="اسلاید قبلی">→</button><button type="button" data-slide-next aria-label="اسلاید بعدی">←</button><button type="button" data-slide-pause aria-pressed="true" aria-label="شروع پخش خودکار">▷</button></div><div class="nc-slider-dots" aria-label="انتخاب اسلاید"><?php foreach ( $slides as $i => $slide ) : ?><button type="button" data-slide-index="<?php echo esc_attr( $i ); ?>" aria-label="<?php echo esc_attr( 'اسلاید ' . ( $i + 1 ) ); ?>" aria-controls="nc-slide-<?php echo esc_attr( $i ); ?>" aria-pressed="<?php echo $i ? 'false' : 'true'; ?>"></button><?php endforeach; ?></div><span class="nc-slider-number" aria-hidden="true">01 / 03</span></div><p class="screen-reader-text nc-slider-status" aria-live="polite"></p></section>
<nav class="nc-market-shortcuts container" aria-label="راه‌های سریع خرید"><?php foreach ( array( array( 'bolt', 'پیشنهادهای ویژه', add_query_arg( 'nc_sale', '1', navid_commerce_shop_url() ) ), array( 'grid', 'همه محصولات', navid_commerce_shop_url() ), array( 'spark', 'تازه‌رسیده‌ها', add_query_arg( 'orderby', 'date', navid_commerce_shop_url() ) ), array( 'heart', 'علاقه‌مندی‌ها', 'wishlist' ), array( 'compare', 'مقایسه کالا', 'compare' ), array( 'eye', 'بازدیدهای اخیر', 'recent' ), array( 'bag', 'سفارش‌های من', function_exists( 'wc_get_account_endpoint_url' ) ? wc_get_account_endpoint_url( 'orders' ) : wp_login_url() ) ) as $item ) : $tool = in_array( $item[2], array( 'wishlist', 'compare', 'recent' ), true ); if ( $tool && ( ! class_exists( 'WooCommerce' ) || ! get_theme_mod( 'navid_shopping_tools', true ) ) ) { continue; } if ( $tool ) : ?><button class="nc-shortcut-tool" type="button" data-open-tool="<?php echo esc_attr( $item[2] ); ?>" aria-haspopup="dialog" aria-controls="nc-shopping-tools"><?php else : ?><a href="<?php echo esc_url( $item[2] ); ?>"><?php endif; ?><span><?php navid_commerce_icon( $item[0] ); ?></span><strong><?php echo esc_html( $item[1] ); ?></strong><?php echo $tool ? '</button>' : '</a>'; endforeach; ?></nav>
