<?php if ( get_theme_mod( 'navid_show_collections', true ) ) : ?><section class="nc-market-promos container" aria-label="کالکشن‌های منتخب"><a class="nc-promo-work" href="<?php echo esc_url( navid_commerce_collection_url( 'laptops' ) ); ?>"><div><small>کار راحت‌تر، روز بهتر</small><h2>میز کار، به سبک تو</h2><span>کشف لوازم کار <?php navid_commerce_icon( 'arrow' ); ?></span></div><img src="<?php echo esc_url( get_theme_file_uri( '/assets/images/keyboard.svg' ) ); ?>" width="400" height="280" loading="lazy" alt=""></a><a class="nc-promo-watch" href="<?php echo esc_url( navid_commerce_collection_url( 'watches', 'navid_featured_category' ) ); ?>"><div><small>برای ریتم زندگی شما</small><h2><?php echo esc_html( get_theme_mod( 'navid_featured_title', 'همراه کوچک، تجربه بزرگ.' ) ); ?></h2><span><?php echo esc_html( get_theme_mod( 'navid_featured_text', 'هوشمندانه‌تر انتخاب کن' ) ); ?> <?php navid_commerce_icon( 'arrow' ); ?></span></div><?php $img = absint( get_theme_mod( 'navid_featured_image', 0 ) ); if ( $img ) { echo wp_get_attachment_image( $img, 'medium_large', false, array( 'loading' => 'lazy', 'alt' => '' ) ); } else { ?><img src="<?php echo esc_url( get_theme_file_uri( '/assets/images/watch.svg' ) ); ?>" width="400" height="280" loading="lazy" alt=""><?php } ?></a></section><?php endif; ?>
<?php $categories = navid_commerce_categories(); if ( $categories && get_theme_mod( 'navid_show_categories', true ) ) : ?><section class="categories container" aria-labelledby="categories-title"><div class="section-heading"><h2 id="categories-title">خرید بر اساس دسته‌بندی</h2></div><div class="category-grid"><?php foreach ( $categories as $category ) : $url = get_term_link( $category ); if ( is_wp_error( $url ) ) { continue; } ?><a class="category-card" href="<?php echo esc_url( $url ); ?>"><span class="category-art"><?php navid_commerce_category_art( $category ); ?></span><strong><?php echo esc_html( $category->name ); ?></strong><span><?php echo esc_html( number_format_i18n( $category->count ) ); ?> محصول</span></a><?php endforeach; ?></div></section><?php endif; ?>
<?php navid_commerce_product_section( 'تازه‌رسیده‌های فروشگاه' ); navid_commerce_market_category_panels(); ?>
